## File 1: Create `src/hooks/useTasks.tsx`

Hook for task CRUD with realtime:

```typescript
import { useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

export type TaskStatus = "todo" | "in_progress" | "done";
export type TaskPriority = "low" | "medium" | "high";

export interface Task {
  id: string;
  team_id: string;
  title: string;
  description: string | null;
  assigned_to: string | null;
  created_by: string;
  job_id: string | null;
  resume_id: string | null;
  status: TaskStatus;
  priority: TaskPriority;
  due_date: string | null;
  completed_at: string | null;
  created_at: string;
  updated_at: string;
}

export function useTasks(teamId: string | null) {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const queryKey = ["tasks", teamId];

  const { data: tasks = [], isLoading } = useQuery<Task[]>({
    queryKey,
    queryFn: async () => {
      if (!teamId) return [];
      const { data, error } = await (supabase as any)
        .from("tasks")
        .select("*")
        .eq("team_id", teamId)
        .order("created_at", { ascending: false });
      if (error) throw error;
      return data ?? [];
    },
    enabled: !!teamId,
    staleTime: 30_000,
  });

  // Realtime
  useEffect(() => {
    if (!teamId) return;
    const channel = supabase
      .channel(`tasks-${teamId}`)
      .on("postgres_changes", {
        event: "*",
        schema: "public",
        table: "tasks",
        filter: `team_id=eq.${teamId}`,
      }, () => {
        queryClient.invalidateQueries({ queryKey });
      })
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [teamId, queryClient]);

  const createTask = useMutation({
    mutationFn: async (task: {
      title: string;
      description?: string;
      assigned_to?: string;
      job_id?: string;
      priority?: TaskPriority;
      due_date?: string;
    }) => {
      const { error } = await (supabase as any)
        .from("tasks")
        .insert({
          team_id: teamId,
          created_by: user?.id,
          ...task,
        });
      if (error) throw error;
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey }),
  });

  const updateTask = useMutation({
    mutationFn: async ({ id, ...updates }: Partial<Task> & { id: string }) => {
      const payload: any = { ...updates };
      if (updates.status === "done" && !updates.completed_at) {
        payload.completed_at = new Date().toISOString();
      }
      if (updates.status && updates.status !== "done") {
        payload.completed_at = null;
      }
      const { error } = await (supabase as any)
        .from("tasks")
        .update(payload)
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey }),
  });

  const deleteTask = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await (supabase as any)
        .from("tasks")
        .delete()
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey }),
  });

  return { tasks, isLoading, createTask, updateTask, deleteTask };
}
```

## File 2: Create `src/pages/Tasks.tsx`

Full page matching the roadmap mockup. Read `src/pages/Team.tsx` for SidebarLayout pattern.

Structure:
```
SidebarLayout
  main.max-w-3xl.mx-auto.px-4.py-8
    Header: "My Tasks" + badge counts (overdue red, due soon amber) + "+ New Task" button

    // New Task Dialog (Sheet or AlertDialog)
    Dialog with form:
      - Title input (required)
      - Description textarea (optional)
      - Assign to (Select with team members from useTeam)
      - Priority (Select: Low/Medium/High)
      - Due date (Input type="date")
      - Create button

    // Task sections
    {overdueTasks.length > 0 && <Section title="Overdue" variant="destructive" tasks={overdueTasks} />}
    {dueSoonTasks.length > 0 && <Section title="Due Soon" variant="warning" tasks={dueSoonTasks} />}
    {upcomingTasks.length > 0 && <Section title="Upcoming" tasks={upcomingTasks} />}
    {noDueDateTasks.length > 0 && <Section title="No Due Date" tasks={noDueDateTasks} />}
    {completedTasks.length > 0 && <Section title="Completed" tasks={completedTasks} collapsed />}

    // Empty state
    {tasks.length === 0 && !isLoading && EmptyState}
```

Each task row:
- Checkbox (toggles done/todo)
- Title (strikethrough if done)
- Assigned user avatar/initial
- Priority badge (Low=gray, Medium=amber, High=red)
- Due date badge (overdue=red, due soon=amber, future=muted)
- Delete button (trash icon, only for creator/admin)

Use these shadcn components: Card, Button, Input, Textarea, Select, Badge, Checkbox, Dialog/DialogContent/DialogHeader/DialogTitle/DialogTrigger, Skeleton
Icons: CheckSquare, Plus, Trash2, Loader2, Calendar, AlertTriangle, Clock, Flag

Task grouping logic:
```typescript
const today = new Date();
const threeDaysFromNow = addDays(today, 3);

const overdue = tasks.filter(t => t.status !== "done" && t.due_date && isBefore(parseISO(t.due_date), today));
const dueSoon = tasks.filter(t => t.status !== "done" && t.due_date && !isBefore(parseISO(t.due_date), today) && isBefore(parseISO(t.due_date), threeDaysFromNow));
const upcoming = tasks.filter(t => t.status !== "done" && t.due_date && !isBefore(parseISO(t.due_date), threeDaysFromNow));
const noDueDate = tasks.filter(t => t.status !== "done" && !t.due_date);
const completed = tasks.filter(t => t.status === "done");
```

Use date-fns: `isBefore`, `parseISO`, `addDays`, `format`, `isToday`, `isTomorrow`

