import { useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

export type TaskStatus = "todo" | "in_progress" | "done";
export type TaskPriority = "low" | "medium" | "high";

export interface Task {
  id: string;
  team_id: string;
  title: string;
  description: string | null;
  assigned_to: string | null;
  created_by: string;
  job_id: string | null;
  resume_id: string | null;
  status: TaskStatus;
  priority: TaskPriority;
  due_date: string | null;
  completed_at: string | null;
  created_at: string;
  updated_at: string;
}

export function useTasks(teamId: string | null) {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const queryKey = ["tasks", teamId];

  const { data: tasks = [], isLoading } = useQuery<Task[]>({
    queryKey,
    queryFn: async () => {
      if (!teamId) return [];
      const { data, error } = await (supabase as any)
        .from("tasks")
        .select("*")
        .eq("team_id", teamId)
        .order("created_at", { ascending: false });
      if (error) throw error;
      return data ?? [];
    },
    enabled: !!teamId,
    staleTime: 30_000,
  });

  // Realtime
  useEffect(() => {
    if (!teamId) return;
    const channel = supabase
      .channel(`tasks-${teamId}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "tasks",
          filter: `team_id=eq.${teamId}`,
        },
        () => {
          queryClient.invalidateQueries({ queryKey });
        }
      )
      .subscribe();
    return () => {
      supabase.removeChannel(channel);
    };
  }, [teamId, queryClient]);

  const createTask = useMutation({
    mutationFn: async (task: {
      title: string;
      description?: string;
      assigned_to?: string;
      job_id?: string;
      priority?: TaskPriority;
      due_date?: string;
    }) => {
      const { error } = await (supabase as any).from("tasks").insert({
        team_id: teamId,
        created_by: user?.id,
        ...task,
      });
      if (error) throw error;
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey }),
  });

  const updateTask = useMutation({
    mutationFn: async ({ id, ...updates }: Partial<Task> & { id: string }) => {
      const payload: Record<string, unknown> = { ...updates };
      if (updates.status === "done" && !updates.completed_at) {
        payload.completed_at = new Date().toISOString();
      }
      if (updates.status && updates.status !== "done") {
        payload.completed_at = null;
      }
      const { error } = await (supabase as any)
        .from("tasks")
        .update(payload)
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey }),
  });

  const deleteTask = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await (supabase as any)
        .from("tasks")
        .delete()
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey }),
  });

  return { tasks, isLoading, createTask, updateTask, deleteTask };
}

import { useState } from "react";
import { toast } from "sonner";
import {
  isBefore,
  parseISO,
  addDays,
  format,
  isToday,
  isTomorrow,
} from "date-fns";
import {
  CheckSquare,
  Plus,
  Trash2,
  Loader2,
  Calendar,
  AlertTriangle,
  Clock,
  Flag,
  ChevronDown,
  ChevronRight,
} from "lucide-react";
import SidebarLayout from "@/components/SidebarLayout";
import { FadeIn } from "@/components/ui/fade-in";
import { StaggerList } from "@/components/ui/stagger-list";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { useTasks, type Task, type TaskPriority } from "@/hooks/useTasks";
import { useTeam } from "@/hooks/useTeam";
import { useAuth } from "@/hooks/useAuth";

// ── helpers ──────────────────────────────────────────────────────────────────

function formatDueDate(dateStr: string): string {
  const d = parseISO(dateStr);
  if (isToday(d)) return "Today";
  if (isTomorrow(d)) return "Tomorrow";
  return format(d, "MMM d");
}

// ── priority badge ────────────────────────────────────────────────────────────

const PRIORITY_CONFIG: Record<
  TaskPriority,
  { label: string; className: string }
> = {
  low: { label: "Low", className: "bg-muted text-muted-foreground" },
  medium: { label: "Medium", className: "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400" },
  high: { label: "High", className: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400" },
};

function PriorityBadge({ priority }: { priority: TaskPriority }) {
  const { label, className } = PRIORITY_CONFIG[priority];
  return (
    <span
      className={`inline-flex items-center gap-1 text-[10px] font-semibold px-1.5 py-0.5 rounded-full ${className}`}
    >
      <Flag className="h-2.5 w-2.5" />
      {label}
    </span>
  );
}

// ── due date badge ────────────────────────────────────────────────────────────

function DueDateBadge({ dueDate, isDone }: { dueDate: string; isDone: boolean }) {
  const today = new Date();
  const d = parseISO(dueDate);
  const overdue = !isDone && isBefore(d, today);
  const soon = !isDone && !overdue && isBefore(d, addDays(today, 3));

  const className = overdue
    ? "text-red-600 dark:text-red-400"
    : soon
    ? "text-amber-600 dark:text-amber-400"
    : "text-muted-foreground";

  return (
    <span className={`inline-flex items-center gap-1 text-xs ${className}`}>
      <Calendar className="h-3 w-3" />
      {formatDueDate(dueDate)}
    </span>
  );
}

// ── assignee avatar ───────────────────────────────────────────────────────────

function AssigneeAvatar({
  userId,
  members,
}: {
  userId: string;
  members: { user_id: string; email?: string }[];
}) {
  const member = members.find((m) => m.user_id === userId);
  const label = member?.email
    ? member.email[0].toUpperCase()
    : userId.slice(0, 1).toUpperCase();
  const title = member?.email ?? userId;

  return (
    <span
      title={title}
      className="inline-flex items-center justify-center h-5 w-5 rounded-full bg-primary/10 text-primary text-[10px] font-semibold shrink-0"
    >
      {label}
    </span>
  );
}

// ── task row ──────────────────────────────────────────────────────────────────

interface TaskRowProps {
  task: Task;
  members: { user_id: string; email?: string }[];
  currentUserId: string;
  isAdmin: boolean;
  onToggle: (task: Task) => void;
  onDelete: (id: string) => void;
  isDeleting: boolean;
}

function TaskRow({
  task,
  members,
  currentUserId,
  isAdmin,
  onToggle,
  onDelete,
  isDeleting,
}: TaskRowProps) {
  const isDone = task.status === "done";
  const canDelete = task.created_by === currentUserId || isAdmin;

  return (
    <div className="flex items-center gap-3 px-4 py-2.5 group hover:bg-muted/30 transition-colors rounded-lg">
      <Checkbox
        checked={isDone}
        onCheckedChange={() => onToggle(task)}
        className="shrink-0"
        aria-label={isDone ? "Mark as todo" : "Mark as done"}
      />

      <div className="flex-1 min-w-0">
        <p
          className={`text-sm leading-snug truncate ${
            isDone ? "line-through text-muted-foreground" : "text-foreground"
          }`}
        >
          {task.title}
        </p>
        {task.description && (
          <p className="text-xs text-muted-foreground truncate mt-0.5">
            {task.description}
          </p>
        )}
      </div>

      <div className="hidden sm:flex items-center gap-2 shrink-0">
        {task.assigned_to && (
          <AssigneeAvatar userId={task.assigned_to} members={members} />
        )}
        <PriorityBadge priority={task.priority} />
        {task.due_date && (
          <DueDateBadge dueDate={task.due_date} isDone={isDone} />
        )}
      </div>

      {canDelete && (
        <AlertDialog>
          <AlertDialogTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7 opacity-0 group-hover:opacity-100 text-muted-foreground hover:text-destructive shrink-0 transition-opacity"
              disabled={isDeleting}
              aria-label="Delete task"
            >
              {isDeleting ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
              ) : (
                <Trash2 className="h-3.5 w-3.5" />
              )}
            </Button>
          </AlertDialogTrigger>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Delete task?</AlertDialogTitle>
              <AlertDialogDescription>
                "{task.title}" will be permanently deleted. This cannot be undone.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancel</AlertDialogCancel>
              <AlertDialogAction
                onClick={() => onDelete(task.id)}
                className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              >
                Delete
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      )}
    </div>
  );
}

// ── task section ──────────────────────────────────────────────────────────────

interface SectionProps {
  title: string;
  tasks: Task[];
  icon?: React.ReactNode;
  variant?: "default" | "destructive" | "warning";
  collapsed?: boolean;
  members: { user_id: string; email?: string }[];
  currentUserId: string;
  isAdmin: boolean;
  onToggle: (task: Task) => void;
  onDelete: (id: string) => void;
  deletingId: string | null;
}

function TaskSection({
  title,
  tasks,
  icon,
  variant = "default",
  collapsed: defaultCollapsed = false,
  members,
  currentUserId,
  isAdmin,
  onToggle,
  onDelete,
  deletingId,
}: SectionProps) {
  const [open, setOpen] = useState(!defaultCollapsed);

  const titleColor =
    variant === "destructive"
      ? "text-red-600 dark:text-red-400"
      : variant === "warning"
      ? "text-amber-600 dark:text-amber-400"
      : "text-foreground";

  return (
    <div>
      <button
        onClick={() => setOpen((v) => !v)}
        className="flex items-center gap-2 mb-1 w-full text-left py-1 rounded-md hover:bg-muted/40 transition-colors px-1"
      >
        {open ? (
          <ChevronDown className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
        ) : (
          <ChevronRight className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
        )}
        {icon}
        <span className={`text-xs font-semibold uppercase tracking-wider ${titleColor}`}>
          {title}
        </span>
        <Badge variant="secondary" className="text-[10px] h-4 px-1.5 ml-auto">
          {tasks.length}
        </Badge>
      </button>

      {open && (
        <div className="space-y-0.5">
          {tasks.map((task) => (
            <TaskRow
              key={task.id}
              task={task}
              members={members}
              currentUserId={currentUserId}
              isAdmin={isAdmin}
              onToggle={onToggle}
              onDelete={onDelete}
              isDeleting={deletingId === task.id}
            />
          ))}
        </div>
      )}
    </div>
  );
}

// ── skeleton ──────────────────────────────────────────────────────────────────

function TasksSkeleton() {
  return (
    <div className="space-y-3">
      {[1, 2, 3, 4].map((i) => (
        <div key={i} className="flex items-center gap-3 px-4 py-2.5">
          <Skeleton className="h-4 w-4 rounded shrink-0" />
          <Skeleton className="h-4 flex-1" />
          <Skeleton className="h-4 w-24 hidden sm:block" />
        </div>
      ))}
    </div>
  );
}

// ── new task dialog ───────────────────────────────────────────────────────────

interface NewTaskDialogProps {
  members: { user_id: string; email?: string }[];
  isCreating: boolean;
  onSubmit: (values: {
    title: string;
    description?: string;
    assigned_to?: string;
    priority: TaskPriority;
    due_date?: string;
  }) => void;
}

function NewTaskDialog({ members, isCreating, onSubmit }: NewTaskDialogProps) {
  const [open, setOpen] = useState(false);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [assignedTo, setAssignedTo] = useState<string>("__none__");
  const [priority, setPriority] = useState<TaskPriority>("medium");
  const [dueDate, setDueDate] = useState("");

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!title.trim()) return;
    onSubmit({
      title: title.trim(),
      description: description.trim() || undefined,
      assigned_to: assignedTo !== "__none__" ? assignedTo : undefined,
      priority,
      due_date: dueDate || undefined,
    });
    // reset
    setTitle("");
    setDescription("");
    setAssignedTo("__none__");
    setPriority("medium");
    setDueDate("");
    setOpen(false);
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button size="sm" className="gap-1.5">
          <Plus className="h-4 w-4" />
          New Task
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Create task</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4 pt-2">
          <div className="space-y-1.5">
            <label className="text-sm font-medium" htmlFor="task-title">
              Title <span className="text-destructive">*</span>
            </label>
            <Input
              id="task-title"
              placeholder="e.g. Review resumes for frontend role"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
              autoFocus
            />
          </div>

          <div className="space-y-1.5">
            <label className="text-sm font-medium" htmlFor="task-desc">
              Description
            </label>
            <Textarea
              id="task-desc"
              placeholder="Optional notes or context…"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={2}
              className="resize-none"
            />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <label className="text-sm font-medium">Assign to</label>
              <Select value={assignedTo} onValueChange={setAssignedTo}>
                <SelectTrigger>
                  <SelectValue placeholder="Unassigned" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="__none__">Unassigned</SelectItem>
                  {members.map((m) => (
                    <SelectItem key={m.user_id} value={m.user_id}>
                      {m.email ?? m.user_id.slice(0, 8) + "…"}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-medium">Priority</label>
              <Select
                value={priority}
                onValueChange={(v) => setPriority(v as TaskPriority)}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="low">Low</SelectItem>
                  <SelectItem value="medium">Medium</SelectItem>
                  <SelectItem value="high">High</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-sm font-medium" htmlFor="task-due">
              Due date
            </label>
            <Input
              id="task-due"
              type="date"
              value={dueDate}
              onChange={(e) => setDueDate(e.target.value)}
            />
          </div>

          <div className="flex justify-end gap-2 pt-1">
            <Button
              type="button"
              variant="outline"
              onClick={() => setOpen(false)}
              disabled={isCreating}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={isCreating || !title.trim()}>
              {isCreating ? (
                <Loader2 className="h-4 w-4 animate-spin mr-1.5" />
              ) : null}
              Create
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

// ── main page ─────────────────────────────────────────────────────────────────

const Tasks = () => {
  const { user, isAdmin } = useAuth();
  const { team, members } = useTeam();
  const teamId = team?.id ?? null;
  const { tasks, isLoading, createTask, updateTask, deleteTask } =
    useTasks(teamId);

  const [deletingId, setDeletingId] = useState<string | null>(null);

  const today = new Date();
  const threeDaysFromNow = addDays(today, 3);

  const overdueTasks = tasks.filter(
    (t) =>
      t.status !== "done" &&
      t.due_date &&
      isBefore(parseISO(t.due_date), today)
  );
  const dueSoonTasks = tasks.filter(
    (t) =>
      t.status !== "done" &&
      t.due_date &&
      !isBefore(parseISO(t.due_date), today) &&
      isBefore(parseISO(t.due_date), threeDaysFromNow)
  );
  const upcomingTasks = tasks.filter(
    (t) =>
      t.status !== "done" &&
      t.due_date &&
      !isBefore(parseISO(t.due_date), threeDaysFromNow)
  );
  const noDueDateTasks = tasks.filter(
    (t) => t.status !== "done" && !t.due_date
  );
  const completedTasks = tasks.filter((t) => t.status === "done");

  async function handleToggle(task: Task) {
    const newStatus = task.status === "done" ? "todo" : "done";
    try {
      await updateTask.mutateAsync({ id: task.id, status: newStatus });
    } catch {
      toast.error("Failed to update task");
    }
  }

  async function handleDelete(id: string) {
    setDeletingId(id);
    try {
      await deleteTask.mutateAsync(id);
      toast.success("Task deleted");
    } catch {
      toast.error("Failed to delete task");
    } finally {
      setDeletingId(null);
    }
  }

  async function handleCreate(values: {
    title: string;
    description?: string;
    assigned_to?: string;
    priority: TaskPriority;
    due_date?: string;
  }) {
    try {
      await createTask.mutateAsync(values);
      toast.success("Task created");
    } catch {
      toast.error("Failed to create task");
    }
  }

  const sectionProps = {
    members,
    currentUserId: user?.id ?? "",
    isAdmin: !!isAdmin,
    onToggle: handleToggle,
    onDelete: handleDelete,
    deletingId,
  };

  const hasActiveTasks =
    overdueTasks.length +
      dueSoonTasks.length +
      upcomingTasks.length +
      noDueDateTasks.length >
    0;

  return (
    <SidebarLayout>
      <main className="w-full max-w-3xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <FadeIn>
          {/* Page header */}
          <div className="flex items-center justify-between mb-1">
            <div className="flex items-center gap-2">
              <h1 className="text-xl font-semibold text-foreground tracking-tight">
                My Tasks
              </h1>
              {overdueTasks.length > 0 && (
                <Badge className="bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400 border-0 text-xs">
                  {overdueTasks.length} overdue
                </Badge>
              )}
              {dueSoonTasks.length > 0 && (
                <Badge className="bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400 border-0 text-xs">
                  {dueSoonTasks.length} due soon
                </Badge>
              )}
            </div>
            <NewTaskDialog
              members={members}
              isCreating={createTask.isPending}
              onSubmit={handleCreate}
            />
          </div>
          <p className="text-sm text-muted-foreground mb-6">
            Track action items and follow-ups across your team.
          </p>
        </FadeIn>

        {/* Loading */}
        {isLoading && (
          <Card>
            <CardContent className="py-3">
              <TasksSkeleton />
            </CardContent>
          </Card>
        )}

        {/* No team state */}
        {!isLoading && !teamId && (
          <div className="flex flex-col items-center justify-center py-16 space-y-4 text-center">
            <div className="rounded-xl bg-muted/50 p-4">
              <CheckSquare className="h-7 w-7 text-muted-foreground/50" />
            </div>
            <div className="space-y-1">
              <p className="text-sm font-medium">No team yet</p>
              <p className="text-sm text-muted-foreground max-w-xs">
                Create or join a team to start managing tasks collaboratively.
              </p>
            </div>
          </div>
        )}

        {/* Empty state */}
        {!isLoading && teamId && tasks.length === 0 && (
          <div className="flex flex-col items-center justify-center py-16 space-y-4 text-center">
            <div className="rounded-xl bg-muted/50 p-4">
              <CheckSquare className="h-7 w-7 text-muted-foreground/50" />
            </div>
            <div className="space-y-1">
              <p className="text-sm font-medium">No tasks yet</p>
              <p className="text-sm text-muted-foreground max-w-xs">
                Create your first task to track action items and follow-ups.
              </p>
            </div>
            <NewTaskDialog
              members={members}
              isCreating={createTask.isPending}
              onSubmit={handleCreate}
            />
          </div>
        )}

        {/* Task sections */}
        {!isLoading && teamId && (hasActiveTasks || completedTasks.length > 0) && (
          <StaggerList className="space-y-5" stagger={0.06}>
            {overdueTasks.length > 0 && (
              <Card>
                <CardContent className="py-3">
                  <TaskSection
                    title="Overdue"
                    tasks={overdueTasks}
                    variant="destructive"
                    icon={<AlertTriangle className="h-3.5 w-3.5 text-red-500 shrink-0" />}
                    {...sectionProps}
                  />
                </CardContent>
              </Card>
            )}

            {dueSoonTasks.length > 0 && (
              <Card>
                <CardContent className="py-3">
                  <TaskSection
                    title="Due Soon"
                    tasks={dueSoonTasks}
                    variant="warning"
                    icon={<Clock className="h-3.5 w-3.5 text-amber-500 shrink-0" />}
                    {...sectionProps}
                  />
                </CardContent>
              </Card>
            )}

            {upcomingTasks.length > 0 && (
              <Card>
                <CardContent className="py-3">
                  <TaskSection
                    title="Upcoming"
                    tasks={upcomingTasks}
                    icon={<Calendar className="h-3.5 w-3.5 text-muted-foreground shrink-0" />}
                    {...sectionProps}
                  />
                </CardContent>
              </Card>
            )}

            {noDueDateTasks.length > 0 && (
              <Card>
                <CardContent className="py-3">
                  <TaskSection
                    title="No Due Date"
                    tasks={noDueDateTasks}
                    {...sectionProps}
                  />
                </CardContent>
              </Card>
            )}

            {completedTasks.length > 0 && (
              <Card>
                <CardContent className="py-3">
                  <TaskSection
                    title="Completed"
                    tasks={completedTasks}
                    collapsed
                    {...sectionProps}
                  />
                </CardContent>
              </Card>
            )}
          </StaggerList>
        )}
      </main>
    </SidebarLayout>
  );
};

export default Tasks;
